/**
 * Arabe.
 *
 * Écran par écran, jamais à moitié : un écran traduit l'est en entier. Les
 * quatorze vues et l'ossature qui les pilote — confirmations, messages de
 * succès, motifs proposés dans une liste — sont couvertes ; ce qui ne l'est
 * pas est nommé à l'utilisateur dans le sélecteur de langue, et ce sont des
 * refus, pas des retards : le texte saisi par un vendeur, et le contenu figé
 * d'un document commercial.
 *
 * `tests/unit/i18n.test.ts` refuse qu'une clé n'existe que d'un seul côté, et
 * refuse aussi qu'une vue ou l'ossature écrive du français en dur au lieu de
 * passer par `t()`. L'annonce de couverture est donc vérifiée, pas affirmée.
 */
